#include <stdio.h>
#include <stdlib.h>

// Define the structure for a linked list node
typedef struct Node {
    long value;
    struct Node* next;
} Node;

// Define the head of the linked list
Node* head = NULL;

// Define the used variable to keep track of the number of nodes
int used = 0;

// Define the value array to store the values of the nodes
long value[100];

// Define the next array to store the next pointers of the nodes
int next[100];

int main(int argc, char** argv) {
    // Check if the number of arguments is less than 2
    if (argc < 2) {
        printf("EMPTY\n");
        return 0;
    }

    // Iterate over the arguments
    for (int i = 1; i < argc; i++) {
        // Convert the argument to a long integer
        long val = strtol(argv[i], NULL, 10);

        // Insert the value into the linked list
        Node* newNode = (Node*) malloc(sizeof(Node));
        newNode->value = val;
        newNode->next = NULL;

        // If the list is empty, set the head to the new node
        if (head == NULL) {
            head = newNode;
        } else {
            // Otherwise, insert the new node into the sorted list
            Node* current = head;
            while (current->next != NULL && current->next->value < val) {
                current = current->next;
            }
            newNode->next = current->next;
            current->next = newNode;
        }
    }

    // Print the sorted list
    Node* current = head;
    while (current != NULL) {
        printf("%ld ", current->value);
        current = current->next;
    }
    printf("\n");

    return 0;
}
